def to_chinese_numeral(n):
    # Handling negative numbers
    if n < 0:
        return '负' + to_chinese_numeral(-n)

    # Handling zero
    if n == 0:
        return '零'

    # Helper function to convert digits to Chinese numerals
    def digit_to_chinese(digit):
        if digit == 1:
            return '一'
        elif digit == 2:
            return '二'
        elif digit == 3:
            return '三'
        elif digit == 4:
            return '四'
        elif digit == 5:
            return '五'
        elif digit == 6:
            return '六'
        elif digit == 7:
            return '七'
        elif digit == 8:
            return '八'
        elif digit == 9:
            return '九'
        else:
            return ''

    # Helper function to convert a number with a specific place multiplier to Chinese numerals
    def number_to_chinese(number, multiplier):
        if number == 0:
            return ''
        else:
            return digit_to_chinese(number) + multiplier

    # Helper function to convert a number to Chinese numerals
    def num_to_chinese(num):
        # Splitting the number into integer and decimal parts
        integer_part, decimal_part = str(num).split('.')

        # Converting the integer part to Chinese numerals
        chinese_numeral = ''
        i = len(integer_part) - 1
        while i >= 0:
            if integer_part[i] != '0':
                chinese_numeral = number_to_chinese(int(integer_part[i]), '千') + chinese_numeral
            i -= 1

        # Adding the decimal point
        if decimal_part != '0':
            chinese_numeral += '点'

        # Converting the decimal part to Chinese numerals
        for digit in decimal_part:
            chinese_numeral += digit_to_chinese(int(digit))

        return chinese_numeral

    return num_to_chinese(n)
